select is((tests.as_user('{"sub":"15cb7ec0-e7cd-4367-aad5-e46790f5d3e0","role":"authenticated","aal":"aal2","app_metadata":{"role":"clinic_admin","clinic_id":"d0579ad3-d8ff-44f0-bd72-00a2011c1fc5"}}'::jsonb, 'insert into public.webhook_deliveries (id, endpoint_id, clinic_id, event, status, attempts, last_attempt_at, object_id, body, signature) select gen_random_uuid(), endpoint_id, clinic_id, event, status, attempts, last_attempt_at, object_id, body, signature from public.webhook_deliveries limit 1')).n, -1, 'webhook deliveries: the outbox itself stays the system’s');

