select is(tests.value_as('{"sub":"024b89fe-e0d0-4550-b796-5353f86b3486","role":"authenticated","aal":"aal1","app_metadata":{"role":"hr","company_id":"20c1d1ef-6ac4-48b2-87ea-7e9728d9d5f2"}}'::jsonb, 'select app.fact_advance_deal(''75014162-224a-4052-a6fa-fcdf96ffa1ca'', ''active'', array[''lead'', ''census'', ''quote'', ''kp_sent'', ''kp_accepted'', ''contract_draft'', ''contract_review'', ''contract_sent'', ''signing'', ''awaiting_payment'', ''active''], now())::text'), (select (stage <> 'lost')::text from public.deals where id = '75014162-224a-4052-a6fa-fcdf96ffa1ca'), 'advance deal: HR of the own company');

