-- app.fact_redeem_card_token / app.fact_match_policy_pinfl: a clinic checking a patient, nobody else
insert into public.card_tokens (token, short_code, insured_id, expires_at) values ('t-redeem', 'EEEE5555', '3bbd3ada-60b7-451a-9ad3-30daa667beb1', (extract(epoch from now()) * 1000)::bigint + 600000);
select is(tests.value_as('{"sub":"d87d459d-1000-4b7d-b5fd-369cf3032aaf","role":"authenticated","aal":"aal2","app_metadata":{"role":"clinic_registrar","clinic_id":"d0579ad3-d8ff-44f0-bd72-00a2011c1fc5"}}'::jsonb, 'select app.fact_redeem_card_token(''EEEE5555'', null, (extract(epoch from now()) * 1000)::bigint) ->> ''insuredId'''), '3bbd3ada-60b7-451a-9ad3-30daa667beb1', 'card code: the clinic gets only the person id');
update public.card_tokens set used_at = 1 where token = 't-redeem';
select is(tests.value_as('{"sub":"d87d459d-1000-4b7d-b5fd-369cf3032aaf","role":"authenticated","aal":"aal2","app_metadata":{"role":"clinic_registrar","clinic_id":"d0579ad3-d8ff-44f0-bd72-00a2011c1fc5"}}'::jsonb, 'select app.fact_redeem_card_token(''EEEE5555'', null, (extract(epoch from now()) * 1000)::bigint) ->> ''status'''), 'used', 'card code: a second use is refused');
select is(tests.value_as('{"sub":"d87d459d-1000-4b7d-b5fd-369cf3032aaf","role":"authenticated","aal":"aal2","app_metadata":{"role":"clinic_registrar","clinic_id":"d0579ad3-d8ff-44f0-bd72-00a2011c1fc5"}}'::jsonb, 'select app.fact_redeem_card_token(null, ''no-such-token-0000'', (extract(epoch from now()) * 1000)::bigint) ->> ''status'''), 'stale', 'card code: an unknown code is stale');
select is(tests.value_as('{"sub":"54bc4a41-9856-4a1e-a53b-a0ee976f364e","role":"authenticated","aal":"aal2","app_metadata":{"role":"operator"}}'::jsonb, 'select app.fact_redeem_card_token(''EEEE5555'', null, 0)::text'), 'denied', 'card code: MIG staff do not redeem codes');
select is(tests.value_as('{"sub":"59f577ba-4115-4ea2-ba60-f2454cb8ffc1","role":"authenticated","aal":"aal1","app_metadata":{"role":"insured","insured_id":"3bbd3ada-60b7-451a-9ad3-30daa667beb1"}}'::jsonb, 'select app.fact_redeem_card_token(''EEEE5555'', null, 0)::text'), 'denied', 'card code: the insured person does not redeem codes');
select is(tests.value_as('{"sub":"d87d459d-1000-4b7d-b5fd-369cf3032aaf","role":"authenticated","aal":"aal2","app_metadata":{"role":"clinic_registrar","clinic_id":"d0579ad3-d8ff-44f0-bd72-00a2011c1fc5"}}'::jsonb, 'select app.fact_match_policy_pinfl(''dms-2026-000101'', ''\x8ee61637cd291efd59b3ef776a94a4b504c487d65b5573e7cbbaa41b6f8773b7'')::text'), '3bbd3ada-60b7-451a-9ad3-30daa667beb1', 'policy and PINFL: the clinic gets the person id (any case of the number)');
select is(tests.value_as('{"sub":"d87d459d-1000-4b7d-b5fd-369cf3032aaf","role":"authenticated","aal":"aal2","app_metadata":{"role":"clinic_registrar","clinic_id":"d0579ad3-d8ff-44f0-bd72-00a2011c1fc5"}}'::jsonb, 'select app.fact_match_policy_pinfl(''DMS-2026-000101'', ''\x00'')::text'), null, 'policy and PINFL: a wrong PINFL matches nobody');
select is(tests.value_as('{"sub":"024b89fe-e0d0-4550-b796-5353f86b3486","role":"authenticated","aal":"aal1","app_metadata":{"role":"hr","company_id":"20c1d1ef-6ac4-48b2-87ea-7e9728d9d5f2"}}'::jsonb, 'select app.fact_match_policy_pinfl(''DMS-2026-000101'', ''\x00'')::text'), 'denied', 'policy and PINFL: HR is refused');

