select is(tests.value_as('{"sub":"d87d459d-1000-4b7d-b5fd-369cf3032aaf","role":"authenticated","aal":"aal2","app_metadata":{"role":"clinic_registrar","clinic_id":"d0579ad3-d8ff-44f0-bd72-00a2011c1fc5"}}'::jsonb, 'select (app.fact_visit_patient(''8d7907fa-9d87-462c-9054-1e4333dd8978'') ? ''pinfl'')::text'), 'false', 'visit patient: only the name and the policy');
select is(tests.value_as('{"sub":"d87d459d-1000-4b7d-b5fd-369cf3032aaf","role":"authenticated","aal":"aal2","app_metadata":{"role":"clinic_registrar","clinic_id":"d0579ad3-d8ff-44f0-bd72-00a2011c1fc5"}}'::jsonb, 'select app.fact_visit_patient(''fdf7ee2d-2fed-4163-bb2d-f4779a5607d8'')::text'), 'denied', 'visit patient: not a visit of another clinic');
select is(tests.value_as('{"sub":"d87d459d-1000-4b7d-b5fd-369cf3032aaf","role":"authenticated","aal":"aal2","app_metadata":{"role":"clinic_registrar","clinic_id":"d0579ad3-d8ff-44f0-bd72-00a2011c1fc5"}}'::jsonb, 'select app.fact_visit_policy_period(''8d7907fa-9d87-462c-9054-1e4333dd8978'') ->> ''endDate'''), (select p.end_date::text from public.insured i join public.policies p on p.id = i.policy_id where i.id = '49889f6d-0de4-43ee-ac91-22aaad48b839'), 'visit policy period: the term of the patient’s policy');
select is(tests.value_as('{"sub":"d87d459d-1000-4b7d-b5fd-369cf3032aaf","role":"authenticated","aal":"aal2","app_metadata":{"role":"clinic_registrar","clinic_id":"d0579ad3-d8ff-44f0-bd72-00a2011c1fc5"}}'::jsonb, 'select app.fact_visit_policy_period(''fdf7ee2d-2fed-4163-bb2d-f4779a5607d8'')::text'), 'denied', 'visit policy period: not of another clinic’s visit');
select is(tests.value_as('{"sub":"59f577ba-4115-4ea2-ba60-f2454cb8ffc1","role":"authenticated","aal":"aal1","app_metadata":{"role":"insured","insured_id":"3bbd3ada-60b7-451a-9ad3-30daa667beb1"}}'::jsonb, 'select app.fact_visit_patient(''8d7907fa-9d87-462c-9054-1e4333dd8978'')::text'), 'denied', 'visit patient: the insured person is refused');

