select is(tests.value_as('{"sub":"63e6a77c-6970-4fc6-8839-87e3f7ed5d36","role":"authenticated","aal":"aal2","app_metadata":{"role":"asst_operator","assistance_id":"a121b4af-f33d-4698-aa49-81543ec9c8af"}}'::jsonb, 'select jsonb_array_length(app.fact_policy_routing(''37c1a764-fb1e-49c1-bccc-71f79d27235f''))'), (select count(*)::text from public.assignments where policy_id = '37c1a764-fb1e-49c1-bccc-71f79d27235f'), 'routing: an assistance company of a policy it served (all companies of it)');
select is(tests.value_as('{"sub":"63e6a77c-6970-4fc6-8839-87e3f7ed5d36","role":"authenticated","aal":"aal2","app_metadata":{"role":"asst_operator","assistance_id":"a121b4af-f33d-4698-aa49-81543ec9c8af"}}'::jsonb, 'select app.fact_policy_routing(''7e2e38e1-9a33-49c5-b971-4baf8e291136'')::text'), 'denied', 'routing: not of a policy the company never served');
select is(tests.value_as('{"sub":"63e6a77c-6970-4fc6-8839-87e3f7ed5d36","role":"authenticated","aal":"aal2","app_metadata":{"role":"asst_operator","assistance_id":"a121b4af-f33d-4698-aa49-81543ec9c8af"}}'::jsonb, 'select bool_and(not (x ? ''setById'') and not (x ? ''setAt''))::text from jsonb_array_elements(app.fact_policy_routing(''37c1a764-fb1e-49c1-bccc-71f79d27235f'')) x'), 'true', 'routing: no author of the assignment');

