select is((tests.as_user('{"sub":"024b89fe-e0d0-4550-b796-5353f86b3486","role":"authenticated","aal":"aal1","app_metadata":{"role":"hr","company_id":"20c1d1ef-6ac4-48b2-87ea-7e9728d9d5f2"}}'::jsonb, 'select 1 from public.contracts where id = ''00000000-0000-4000-8000-000000002101''')).n, 1, 'contracts: HR reads the draft while the request is open');
